-- Background job queue (docs/specs/mysql-migration.md §7.2), replacing pg-boss. Read and written only by
-- src/server/jobs/queue.ts, whose SQL is dialect-neutral; task 46 ports this DDL to MySQL.
-- id is generated by the application so enqueue needs no RETURNING.

CREATE TABLE job (
  id uuid PRIMARY KEY,
  name text NOT NULL,
  data jsonb NOT NULL,
  state text NOT NULL DEFAULT 'created' CHECK (state IN ('created', 'active', 'completed', 'failed', 'deadletter')),
  singleton_key text,
  retry_count int NOT NULL DEFAULT 0,
  retry_limit int NOT NULL,
  retry_delay_s int NOT NULL,
  start_after timestamptz NOT NULL,
  -- Visibility timeout of an active job: past it the worker is presumed dead and the job is queued again.
  locked_until timestamptz,
  output jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  -- Set when the job reaches completed, failed or deadletter; retention deletes completed jobs by it.
  finished_at timestamptz
);

-- The 'short' policy: at most one queued job per (name, singleton_key); an active job does not block a new one.
CREATE UNIQUE INDEX job_queued_singleton ON job (name, singleton_key) WHERE state = 'created';

CREATE INDEX job_fetch ON job (name, state, start_after);
